class LoginPage {
  constructor(driver) {
    this.driver = driver;
    this.sel = { user: '#username', pass: '#password', submit: 'button[type=submit]', error: '.error' };
  }
  loginAs(user, pass) {
    this.driver.fill(this.sel.user, user);
    this.driver.fill(this.sel.pass, pass);
    this.driver.click(this.sel.submit);
    return this;
  }
  errorText() {
    return this.driver.text(this.sel.error);
  }
}

