class Header {
  constructor(driver) { this.driver = driver; }
  cartCount() { return Number(this.driver.text('#cart-count')); }
}
class ResultsPage {
  constructor(driver) { this.driver = driver; this.header = new Header(driver); }
  open(index) { this.driver.click(`.result:nth-of-type(${index + 1}) a`); return this; }
  titles() { return this.driver.text('.result h3').split('|'); }
}
class SearchPage {
  constructor(driver) { this.driver = driver; this.header = new Header(driver); }
  search(term) {
    this.driver.fill('#q', term);
    this.driver.click('#search-btn');
    return new ResultsPage(this.driver);
  }
}
